INSERT INTO `site_settings` (`id`, `key`, `value`, `created_at`, `updated_at`) VALUES
  (1, 'home_content', '{"seo":{"title":"Ph\\u00e2n b\\u00f3n h\\u1eefu c\\u01a1 ROOTBIO Vi\\u1ec7t Nam","description":"Ph\\u00e2n b\\u00f3n sinh h\\u1ecdc ROOTBIO - k\\u00edch r\\u1ec5, bung \\u0111\\u1ecdt, h\\u1ebft v\\u00e0ng l\\u00e1 th\\u1ed1i r\\u1ec5 ch\\u1ec9 sau 2 l\\u1ea7n t\\u01b0\\u1edbi. Nh\\u1eadn \\u01b0u \\u0111\\u00e3i t\\u1eb7ng 100 chai d\\u00f9ng th\\u1eed."},"hero":{"brandName":"ROOTBIO","brandTagline":"Ph\\u00e2n b\\u00f3n sinh h\\u1ecdc","brandLetter":"R","navPhone":"0939.393.912","navCtaLabel":"\\u0110\\u0103ng k\\u00fd ngay","badgeText":"Nh\\u1eadn \\u01b0u \\u0111\\u00e3i - T\\u1eb7ng 100 chai d\\u00f9ng th\\u1eed","titlePrefix":"Ph\\u00e2n b\\u00f3n","titleAccent":"ROOTBIO","titleSubtitle":"Ch\\u1ec9 2 l\\u1ea7n phun \\u2013 c\\u00e2y bung \\u0111\\u1ecdt, ra r\\u1ec5 m\\u1ea1nh","description":"Cam k\\u1ebft hi\\u1ec7u qu\\u1ea3 sau 5 - 7 ng\\u00e0y. C\\u00f4ng ngh\\u1ec7 Nano \\u0111\\u1ea1t chu\\u1ea9n Th\\u1ee5y S\\u1ef9, vi l\\u01b0\\u1ee3ng chelate m\\u1ea1nh g\\u1ea5p 10 l\\u1ea7n, axit humic 7% v\\u00e0 7% Kali h\\u1eefu hi\\u1ec7u gi\\u00fap c\\u00e2y h\\u1ebft v\\u00e0ng l\\u00e1, th\\u1ed1i r\\u1ec5, c\\u00f2i c\\u1ecdc.","primaryCtaLabel":"Nh\\u1eadn \\u01b0u \\u0111\\u00e3i","primaryCtaHref":"#dang-ky","secondaryCtaLabel":"Xem hi\\u1ec7u qu\\u1ea3","secondaryCtaHref":"#hieu-qua","features":[{"value":"cam k\\u1ebft hi\\u1ec7u qu\\u1ea3 sau 5 -7 ng\\u00e0y"},{"value":"X100 L\\u1ea6N"},{"value":"C\\u00d4NG NGH\\u1ec6 TI\\u00caN TI\\u1ebeN"},{"value":"Vi l\\u01b0\\u1ee3ng \\u0111\\u1ea7y \\u0111\\u1ee7"},{"value":"Axit Humic 7%"},{"value":"D\\u1ea1ng l\\u1ecfng"},{"value":"NPK 3-3-3"}],"productImage":"\\/images\\/rootbio\\/product.png","productBadgeTitle":"Hi\\u1ec7u qu\\u1ea3 g\\u1ea5p 10 l\\u1ea7n","productBadgeText":"H\\u01a1n 3.826.534 ng\\u01b0\\u1eddi \\u0111\\u00e3 s\\u1eed d\\u1ee5ng v\\u00e0 cho ra hi\\u1ec7u qu\\u1ea3 n\\u0103ng su\\u1ea5t v\\u01b0\\u1ee3t tr\\u1ed9i","floatingBadgeValue":"100","floatingBadgeLabel":"Chai d\\u00f9ng th\\u1eed"},"plantTypes":{"heading":"Gi\\u1ea3i ph\\u00e1p an to\\u00e0n cho m\\u1ecdi lo\\u1ea1i c\\u00e2y","items":[{"value":"C\\u00e2y th\\u00e2n g\\u1ed7"},{"value":"C\\u00e2y Bonsai"},{"value":"C\\u00e2y \\u0103n qu\\u1ea3"},{"value":"C\\u00e2y Rau, c\\u1ee7"},{"value":"C\\u00e1c c\\u00e2y hoa"},{"value":"C\\u00e1c c\\u00e2y c\\u1ea3nh"}]},"problems":{"heading":"B\\u00e0 con \\u0111ang \\u0111au \\u0111\\u1ea7u v\\u1ec1 \\u0111i\\u1ec1u g\\u00ec?","items":[{"title":"C\\u00e2y kh\\u00f4ng ra \\u0111\\u1ecdt, ng\\u1eebng ph\\u00e1t tri\\u1ec3n","description":"C\\u00e2y kh\\u00f4ng ra \\u0111\\u1ecdt, th\\u1eadm ch\\u00ed ng\\u1eebng ph\\u00e1t tri\\u1ec3n d\\u00f9 \\u0111\\u00e3 b\\u00f3n ph\\u00e2n.","image":"\\/images\\/rootbio\\/problem3.png"},{"title":"\\u0110\\u1ea5t chai c\\u1ee9ng, c\\u00e2y kh\\u00f4ng b\\u00e1m r\\u1ec5","description":"\\u0110\\u1ea5t tr\\u1ed3ng l\\u00e2u n\\u0103m b\\u1ecb chai, r\\u1ec5 kh\\u00f4ng th\\u1ec3 l\\u1ea5y dinh d\\u01b0\\u1ee1ng, khi\\u1ebfn c\\u00e2y c\\u00f2i c\\u1ecdc.","image":"\\/images\\/rootbio\\/problem5.webp"},{"title":"C\\u00e2y h\\u00e9o r\\u0169, r\\u1ec5 y\\u1ebfu, d\\u1ec5 ch\\u1ebft","description":"C\\u00e2y non nh\\u01b0ng m\\u00e0 r\\u1ec5 kh\\u00f4ng ph\\u00e1t tri\\u1ec3n, nhanh h\\u00e9o r\\u0169, th\\u1eadm ch\\u00ed ch\\u1ebft c\\u00e2y.","image":"\\/images\\/rootbio\\/problem1.jpg"},{"title":"C\\u00e2y th\\u1ed1i r\\u1ec5, c\\u00e2y suy ki\\u1ec7t","description":"C\\u00e2y y\\u1ebfu, kh\\u00f3 ra \\u0111\\u1ecdt th\\u01b0\\u1eddng b\\u1ecb n\\u1ea5m h\\u1ea1i r\\u1ec5, gi\\u00e2m c\\u00e0nh nh\\u01b0ng kh\\u00f4ng th\\u00e0nh c\\u00f4ng.","image":"\\/images\\/rootbio\\/problem4.jpg"}],"warningTitle":"C\\u1ea3nh b\\u00e1o!","warningText":"C\\u00e2y kh\\u00f3 k\\u00edch r\\u1ec5, k\\u00edch \\u0111\\u1ecdt v\\u00e0 ch\\u1eadm \\u0111\\u1ebb nh\\u00e1nh ch\\u1ee7 y\\u1ebfu do \\u0111\\u1ea5t tr\\u1ed3ng ngh\\u00e8o dinh d\\u01b0\\u1ee1ng, chai c\\u1ee9ng ho\\u1eb7c b\\u1ecb \\u00fang n\\u01b0\\u1edbc, khi\\u1ebfn r\\u1ec5 kh\\u00f4ng th\\u1ec3 ph\\u00e1t tri\\u1ec3n v\\u00e0 h\\u1ea5p thu ch\\u1ea5t c\\u1ea7n thi\\u1ebft. Ngo\\u00e0i ra, vi\\u1ec7c b\\u00f3n ph\\u00e2n kh\\u00f4ng c\\u00e2n \\u0111\\u1ed1i, thi\\u1ebfu vi l\\u01b0\\u1ee3ng quan tr\\u1ecdng c\\u0169ng l\\u00e0m c\\u00e2y suy y\\u1ebfu, kh\\u00f3 ra \\u0111\\u1ecdt v\\u00e0 ch\\u1eadm \\u0111\\u1ebb nh\\u00e1nh.","warningTags":[{"value":"C\\u00c2Y C\\u00d2I C\\u1eccC"},{"value":"C\\u00c2Y V\\u00c0NG L\\u00c1"},{"value":"C\\u00c2Y TH\\u1ed0I R\\u1ec4"},{"value":"\\u0110\\u1ea4T B\\u1ea0C M\\u00c0U"},{"value":"M\\u1ea4T M\\u00d9A, GI\\u1ea2M N\\u0102NG SU\\u1ea4T"}]},"solutions":{"eyebrow":"Ch\\u1ec9 2 l\\u1ea7n phun","heading":"Gi\\u1ea3i quy\\u1ebft ngay c\\u00e1c v\\u1ea5n \\u0111\\u1ec1","description":"Ch\\u1ec9 c\\u1ea7n 2 l\\u1ea7n phun, t\\u00e1i sinh l\\u1ea1i b\\u1ed9 r\\u1ec5, h\\u1ea5p thu dinh d\\u01b0\\u1ee1ng si\\u00eau t\\u1ed1t. M\\u1ea7m, ch\\u1ed3i kh\\u1ecfe m\\u1ea1nh, c\\u00e2y suy kho\\u1ebb l\\u1ea1i th\\u1ea7n k\\u1ef3.","items":[{"title":"H\\u1ebeT V\\u00e0ng L\\u00e1 Th\\u1ed1i R\\u1ec5 sau 2 l\\u1ea7n t\\u01b0\\u1edbi","description":"K\\u00edch th\\u00edch RA R\\u1ec4 nhanh, c\\u00e2y t\\u0103ng tr\\u01b0\\u1edfng m\\u1ea1nh! C\\u00e2y h\\u1ea5p th\\u1ee5 t\\u1ed1i \\u0111a d\\u01b0\\u1ee1ng ch\\u1ea5t, c\\u00e2y nhanh l\\u1edbn, bung \\u0111\\u1ecdt m\\u1ea1nh, k\\u00edch r\\u1ec5 nhanh ph\\u00e1t tri\\u1ec3n g\\u1ea5p 5 l\\u1ea7n sau 2 l\\u1ea7n s\\u1eed d\\u1ee5ng nh\\u1edd 45% l\\u01b0\\u1ee3ng axit humic c\\u00f3 trong s\\u1ea3n ph\\u1ea9m.","image":"\\/images\\/rootbio\\/feature5.png"},{"title":"\\u0110\\u1ea3m b\\u1ea3o t\\u1ef7 l\\u1ec7 k\\u00edch th\\u00edch ra hoa, \\u0111\\u1eadu qu\\u1ea3 l\\u00ean t\\u1edbi 93%","description":"Ch\\u1ec9 sau 2 l\\u1ea7n t\\u01b0\\u1edbi v\\u1edbi 7% Kali h\\u1eefu hi\\u1ec7u. T\\u1ed5ng h\\u1ee3p c\\u00e1c ch\\u1ea5t \\u0111i\\u1ec1u h\\u00f2a sinh tr\\u01b0\\u1edfng, k\\u00edch th\\u00edch qu\\u1ea3, hoa, l\\u00e1 ph\